#!/usr/bin/env node
// Child 01 feasibility probe: talks MCP over stdio to Codex Desktop's cua_repl exactly as .mcp.json
// launches it, runs one `js` call, then `turn_ended`, and records everything (redacted).
//
//   node probe.mjs <variant> [--app "<App Name>"] [--elicit accept|cancel|delay] [--delayMs 60000]
//                            [--timeoutMs 60000] [--out /tmp/cua-probe/out]
//
// variants:
//   a    .mcp.json env verbatim, Codex-shaped _meta, code `await cua.getState()`
//   b    same as a but no _meta at all
//   c    CUA_REPL_ENABLED_SURFACES=computer, NODE_REPL_TRUSTED_SERVICES removed, _meta
//   d    SKY_CUA_SERVICE_PATH -> copy inside @oai/sky (app bundle), _meta
//   app  stage 2: `let app = await cua.getApp(<--app>); await app.getAXState()` with _meta
//
// Only an allow-listed base environment (PATH, HOME, ...) is passed underneath the .mcp.json env so
// shell secrets never reach the runtime. Env values are never logged, only key names.
import { spawn, execFileSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import { appendFile, mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const argv = process.argv.slice(2);
const options = { _: [] };
for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg.startsWith("--")) {
        options[arg.slice(2)] = argv[i + 1];
        i += 1;
    } else options._.push(arg);
}
const variant = options._[0];
const appName = options.app;
const elicitMode = options.elicit ?? "cancel";
const delayMs = Number(options.delayMs ?? 60_000);
const jsTimeoutMs = Number(options.timeoutMs ?? 60_000);
const outDir = options.out ?? "/tmp/cua-probe/out";
const maxWaitMs = Number(options.maxWaitMs ?? 600_000);
if (!["a", "b", "c", "d", "app"].includes(variant)) {
    console.error("variant must be one of a, b, c, d, app");
    process.exit(2);
}
if (variant === "app" && !appName) {
    console.error("--app <name> is required for the app variant");
    process.exit(2);
}

// ---------- resolve the newest enabled .mcp.json ----------
const codexHome = process.env.CODEX_HOME?.trim() || join(homedir(), ".codex");
const cacheDir = join(codexHome, "plugins", "cache", "openai-bundled", "unified-computer-use");
const compareDesc = (a, b) => {
    const pa = a.split(".").map(Number);
    const pb = b.split(".").map(Number);
    for (let i = 0; i < Math.max(pa.length, pb.length); i += 1) {
        const d = (pb[i] ?? 0) - (pa[i] ?? 0);
        if (d !== 0) return d;
    }
    return 0;
};
let server;
let configPath;
for (const version of (await readdir(cacheDir)).sort(compareDesc)) {
    const candidate = join(cacheDir, version, ".mcp.json");
    try {
        const parsed = JSON.parse(await readFile(candidate, "utf8"));
        const entry = parsed.mcpServers?.cua_repl;
        if (entry?.enabled === true && typeof entry.command === "string") {
            server = entry;
            configPath = candidate;
            break;
        }
    } catch {}
}
if (!server) {
    console.error(`no enabled cua_repl .mcp.json under ${cacheDir}`);
    process.exit(2);
}

// ---------- environment ----------
const BASE_ENV_KEYS = ["PATH", "HOME", "USER", "LOGNAME", "TMPDIR", "LANG", "LC_ALL", "SHELL", "TERM"];
const env = {};
for (const key of BASE_ENV_KEYS) if (process.env[key] !== undefined) env[key] = process.env[key];
Object.assign(env, server.env ?? {});
const overrides = {};
let withMeta = true;
if (variant === "b") withMeta = false;
if (variant === "c") {
    env.CUA_REPL_ENABLED_SURFACES = "computer";
    delete env.NODE_REPL_TRUSTED_SERVICES;
    overrides.CUA_REPL_ENABLED_SURFACES = "computer";
    overrides.NODE_REPL_TRUSTED_SERVICES = "(removed)";
}
if (variant === "d") {
    const nodeModules = (env.NODE_REPL_NODE_MODULE_DIRS ?? "").split(":")[0];
    env.SKY_CUA_SERVICE_PATH = join(nodeModules, "@oai", "sky", "Codex Computer Use.app");
    overrides.SKY_CUA_SERVICE_PATH = env.SKY_CUA_SERVICE_PATH;
}

// ---------- redaction + logging ----------
const SECRET_KEY = /token|key|secret|account|password|cookie|authorization/i;
const redact = (value) => {
    if (Array.isArray(value)) return value.map(redact);
    if (value && typeof value === "object") {
        const out = {};
        for (const [k, v] of Object.entries(value)) out[k] = SECRET_KEY.test(k) ? "[redacted]" : redact(v);
        return out;
    }
    return value;
};
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
await mkdir(outDir, { recursive: true });
const logPath = join(outDir, `${variant}-${stamp}.log.jsonl`);
const summaryPath = join(outDir, `${variant}-${stamp}.json`);
const log = async (direction, payload) => {
    await appendFile(logPath, `${JSON.stringify({ t: Date.now(), direction, payload: redact(payload) })}\n`);
};
const pgrep = (pattern) => {
    try {
        return execFileSync("pgrep", ["-f", pattern], { encoding: "utf8" }).trim().split("\n").filter(Boolean).map(Number);
    } catch {
        return [];
    }
};

const summary = {
    variant,
    startedAt: new Date().toISOString(),
    configPath,
    command: server.command,
    args: server.args,
    envKeys: Object.keys(env).sort(),
    overrides,
    withMeta,
    elicitMode,
    appName: appName ?? null,
    servicePidsBefore: pgrep("SkyComputerUseService"),
    cuaPidsBefore: pgrep("cua-repl.mjs"),
    stderr: [],
    notifications: [],
    serverRequests: [],
    elicitations: [],
};

// ---------- JSON-RPC over stdio ----------
const child = spawn(server.command, server.args, { env, stdio: ["pipe", "pipe", "pipe"] });
summary.childPid = child.pid;
let nextId = 1;
const pending = new Map();
let exited = false;
const exitPromise = new Promise((resolve) => {
    child.on("exit", (code, signal) => {
        exited = true;
        summary.childExit = { code, signal, at: new Date().toISOString() };
        for (const [, p] of pending) p.reject(new Error(`transport closed (exit ${code ?? signal})`));
        pending.clear();
        resolve();
    });
});
child.on("error", (error) => {
    summary.spawnError = String(error);
});
child.stderr.on("data", (chunk) => {
    const text = chunk.toString();
    summary.stderr.push(text.slice(0, 2000));
    void log("stderr", text.slice(0, 4000));
});
const send = (message) => {
    void log("->", message);
    child.stdin.write(`${JSON.stringify(message)}\n`);
};
const request = (method, params) =>
    new Promise((resolve, reject) => {
        const id = nextId++;
        pending.set(id, { resolve, reject, method });
        send({ jsonrpc: "2.0", id, method, params });
    });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const handleElicitation = async (message) => {
    const record = {
        receivedAt: new Date().toISOString(),
        id: message.id,
        params: redact(message.params),
    };
    summary.elicitations.push(record);
    console.error(`\n[elicitation/create] ${message.params?.message}\n  _meta: ${JSON.stringify(redact(message.params?._meta ?? {}))}\n  schema: ${JSON.stringify(message.params?.requestedSchema ?? {})}\n  mode: ${elicitMode}`);
    let result;
    if (elicitMode === "accept") result = { action: "accept", content: {} };
    else if (elicitMode === "delay") {
        console.error(`  waiting ${delayMs} ms before answering cancel...`);
        await sleep(delayMs);
        result = { action: "cancel" };
    } else result = { action: "cancel" };
    record.response = result;
    record.respondedAt = new Date().toISOString();
    send({ jsonrpc: "2.0", id: message.id, result });
};

let buffer = "";
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let nl = buffer.indexOf("\n");
    while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf("\n");
        if (!line) continue;
        let message;
        try {
            message = JSON.parse(line);
        } catch {
            void log("<- (raw)", line.slice(0, 4000));
            continue;
        }
        void log("<-", message);
        if (message.id !== undefined && message.method === undefined) {
            const waiter = pending.get(message.id);
            if (!waiter) continue;
            pending.delete(message.id);
            if (message.error) waiter.reject(Object.assign(new Error(message.error.message), { rpc: message.error }));
            else waiter.resolve(message.result);
            continue;
        }
        if (message.method === "elicitation/create") {
            void handleElicitation(message);
            continue;
        }
        if (message.id !== undefined) {
            summary.serverRequests.push({ method: message.method, params: redact(message.params) });
            send({ jsonrpc: "2.0", id: message.id, error: { code: -32601, message: `probe does not implement ${message.method}` } });
            continue;
        }
        summary.notifications.push({ method: message.method, params: redact(message.params) });
    }
});

const describeContent = (content) =>
    (content ?? []).map((block) =>
        block.type === "text"
            ? { type: "text", length: block.text?.length ?? 0, text: (block.text ?? "").slice(0, 20_000) }
            : block.type === "image"
              ? { type: "image", mimeType: block.mimeType, base64Length: block.data?.length ?? 0 }
              : { type: block.type },
    );

const sessionId = randomUUID();
const turnId = randomUUID();
const buildMeta = (callId) => ({
    callId,
    sessionId,
    threadId: sessionId,
    "x-codex-turn-metadata": {
        session_id: sessionId,
        thread_id: sessionId,
        turn_id: turnId,
        model: "gpt-5-codex",
        reasoning_effort: "medium",
        auto_review_enabled: false,
        node_repl_auto_review_required: false,
        node_repl_disabled: false,
        codex_version: "0.160.0",
        turn_started_at_unix_ms: Date.now(),
    },
    "openai/confirmation_policies": {},
});

const finish = async () => {
    summary.finishedAt = new Date().toISOString();
    summary.servicePidsAfter = pgrep("SkyComputerUseService");
    summary.cuaPidsAfter = pgrep("cua-repl.mjs");
    summary.childDescendantsBeforeKill = (() => {
        try {
            return execFileSync("pgrep", ["-P", String(child.pid)], { encoding: "utf8" }).trim().split("\n").filter(Boolean);
        } catch {
            return [];
        }
    })();
    if (!exited) {
        child.stdin.end();
        await Promise.race([exitPromise, sleep(5000)]);
    }
    if (!exited) {
        child.kill("SIGTERM");
        await Promise.race([exitPromise, sleep(3000)]);
    }
    if (!exited) child.kill("SIGKILL");
    await Promise.race([exitPromise, sleep(3000)]);
    summary.cuaPidsAfterClose = pgrep("cua-repl.mjs");
    summary.leakedNodeRepl = (() => {
        const mine = new Set(summary.childDescendantsBeforeKill.map(Number));
        return pgrep("cua_node/bin/node_repl").filter((pid) => mine.has(pid));
    })();
    await writeFile(summaryPath, `${JSON.stringify(summary, null, 2)}\n`);
    console.error(`\nsummary: ${summaryPath}\nlog: ${logPath}`);
};

const guard = setTimeout(async () => {
    summary.verdict = "probe-max-wait-exceeded";
    await finish();
    process.exit(3);
}, maxWaitMs);
guard.unref();

try {
    const t0 = Date.now();
    summary.initialize = await request("initialize", {
        protocolVersion: "2025-06-18",
        capabilities: { elicitation: { form: {} } },
        clientInfo: { name: "codex-mcp-client", title: "Codex", version: "0.160.0" },
    });
    send({ jsonrpc: "2.0", method: "notifications/initialized" });
    const tools = await request("tools/list", {});
    summary.tools = (tools.tools ?? []).map((tool) => ({ name: tool.name, descriptionLength: tool.description?.length ?? 0, annotations: tool.annotations }));
    summary.initializeMs = Date.now() - t0;

    const code =
        variant === "app"
            ? `let app = await cua.getApp(${JSON.stringify(appName)});\nlet ax = await app.getAXState();\ntypeof ax === "string" ? ax : JSON.stringify(ax).slice(0, 8000)`
            : "await cua.getState()";
    const callId = `call_${randomUUID().replace(/-/g, "").slice(0, 24)}`;
    const params = {
        name: "js",
        arguments: { code, timeout_ms: jsTimeoutMs, title: variant === "app" ? `probe: getApp ${appName}`.slice(0, 80) : "probe: cua.getState()" },
    };
    if (withMeta) params._meta = buildMeta(callId);
    summary.jsCall = { code, timeout_ms: jsTimeoutMs, metaKeys: withMeta ? Object.keys(params._meta) : [] };
    console.error(`[js] ${code.replace(/\n/g, " ")}`);
    const t1 = Date.now();
    try {
        const result = await request("tools/call", params);
        summary.jsResult = { isError: result.isError ?? false, content: describeContent(result.content), structuredContent: redact(result.structuredContent), _meta: redact(result._meta), durationMs: Date.now() - t1 };
        summary.verdict = result.isError ? "tool-error" : "result-received";
        const firstText = (result.content ?? []).find((b) => b.type === "text")?.text ?? "";
        console.error(`[js result] isError=${result.isError ?? false} durationMs=${Date.now() - t1}\n${firstText.slice(0, 1500)}`);
    } catch (error) {
        summary.jsResult = { error: error.rpc ?? String(error), durationMs: Date.now() - t1 };
        summary.verdict = error.rpc ? "rpc-error" : "transport-error";
        console.error(`[js error] ${JSON.stringify(summary.jsResult.error).slice(0, 1500)}`);
    }

    const t2 = Date.now();
    try {
        const ended = await request("tools/call", {
            name: "turn_ended",
            arguments: { hook_event_name: "Stop", session_id: sessionId, turn_id: turnId },
        });
        summary.turnEnded = { isError: ended.isError ?? false, content: describeContent(ended.content), durationMs: Date.now() - t2 };
    } catch (error) {
        summary.turnEnded = { error: error.rpc ?? String(error), durationMs: Date.now() - t2 };
    }
    console.error(`[turn_ended] ${JSON.stringify(summary.turnEnded).slice(0, 500)}`);
} catch (error) {
    summary.fatal = String(error);
    summary.verdict = summary.verdict ?? "transport-error";
    console.error(`[fatal] ${error}`);
} finally {
    clearTimeout(guard);
    await finish();
}
